# Let me fix the 3x3 box approach to not overlap with separator
# Dots above sep: create 3x3 box centered at (r+2, c) - shifted down by 2
# Dots below sep: move to (r+1, c) - shifted down by 1

def build_fixed():
    result = [[0]*8 for _ in range(12)]

    # Add separator
    result[3] = [2] * 8

    for r, c in [(0,4), (1,0), (6,1)]:
        if r < 3:  # above sep
            # Create 3x3 box at row r+2 (then r+1, r+2, r+3)
            out_row = r + 2
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = out_row + dr, c + dc
                    if 0 <= nr < 12 and 0 <= nc < 8 and nr != 3:
                        result[nr][nc] = 4
        else:
            # Below sep: move down 1
            if r + 1 < 12:
                result[r + 1][c] = 4

    return result

out = build_fixed()
print("Fixed 3x3 model:")
for row in out:
    print(" ".join(map(str, row)))

