import json

def build_min():
    """Each column keeps only the highest (smallest row) output position."""
    result = [[0]*8 for _ in range(12)]
    result[3] = [2]*8

    # First, compute all shift positions
    positions = []
    for r, c in [(0,4), (1,0), (6,1)]:
        positions.append((r + 1, c))

    # Group by column, keep min row
    col_dict = {}
    for cr, cc in positions:
        if cc not in col_dict:
            col_dict[cc] = []
        col_dict[cc].append(cr)

    for cc in col_dict:
        min_r = min(col_dict[cc])
        if min_r != 3 and 0 <= cc < 8:
            result[min_r][cc] = 4

    return result

grid = build_min()
print("Min per col:", json.dumps({"action": "submit", "grid": grid}))

